<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsToMany;use Illuminate\Database\Eloquent\Relations\HasMany;
class Company extends Model{protected $fillable=['name','slug','description','location','status','country_code','legal_name','tax_id','industry','website','phone','size','verification_status','verification_submitted_at','verification_reviewed_by','verification_reviewed_at','verification_review_note'];protected function casts():array{return ['verification_submitted_at'=>'datetime','verification_reviewed_at'=>'datetime'];}public function jobs():HasMany{return $this->hasMany(Job::class);}public function members():BelongsToMany{return $this->belongsToMany(User::class,'company_members')->withPivot(['role','status'])->withTimestamps();}}
